#include "IMGArchive.h"
namespace ariane::formats { namespace { uint32_t le32(const uint8_t*p){return uint32_t(p[0])|(uint32_t(p[1])<<8)|(uint32_t(p[2])<<16)|(uint32_t(p[3])<<24);} } ImgIndex parseImgV2Directory(const std::vector<uint8_t>& b){ImgIndex r;if(b.size()<8||b[0]!='V'||b[1]!='E'||b[2]!='R'||b[3]!='2'){r.error="Invalid IMG v2 header";return r;}uint32_t n=le32(b.data()+4);if(n>(b.size()-8)/32){r.error="Truncated IMG directory";return r;}r.entries.reserve(n);for(uint32_t i=0;i<n;++i){const uint8_t*p=b.data()+8+size_t(i)*32;size_t len=0;while(len<24&&p[len])++len;std::string name(reinterpret_cast<const char*>(p),len);r.entries.push_back({name,le32(p+24)*2048u,le32(p+28)*2048u});}r.valid=true;return r;} }
